23	type StreamProcessorParams struct {
24		// The backing gRPC bidi stream initiated by zTunnel
25		Stream v3.AggregatedDiscoveryService_DeltaAggregatedResourcesServer
26		// Channel where the StreamProcessor listens for new DeltaDiscoveryRequest.
27		// this is fed directly from Stream.
28		StreamRecv chan *v3.DeltaDiscoveryRequest
29		// Channel where the StreamProcessor listens for Endpoint event.
30		// this is fed by subscribing to EndpointManager.
31		EndpointEventRecv chan *EndpointEvent
32		// Reference to agent's CEP watcher and resource cache.
33		// This will be the source of truth for serving WDS API.
34		K8sCiliumEndpointsWatcher *watchers.K8sCiliumEndpointsWatcher
35		Log                       *slog.Logger
36	}
37	
38	// StreamProcessor implements the logic for handling xDS streams to zTunnel.
39	// It is abstracted away from the primary stream initialization handler to
40	// promote decoupling and the handling multiple streams without a shared set of
41	// channels being required on the Server object.
42	type StreamProcessor struct {
43		stream         v3.AggregatedDiscoveryService_DeltaAggregatedResourcesServer
44		streamRecv     chan *v3.DeltaDiscoveryRequest
45		endpointRecv   chan *EndpointEvent
46		expectedNonce  map[string]struct{}
47		log            *slog.Logger
48		endpointSource EndpointEventSource
49	}
50	
51	// EndpointSource provides data for XDS server from different data sources in the agent.
52	type EndpointSource struct {
53		k8sCiliumEndpointsWatcher *watchers.K8sCiliumEndpointsWatcher
54		sp                        *StreamProcessor
55	}
56	
57	func NewEndpointSource(k *watchers.K8sCiliumEndpointsWatcher, sp *StreamProcessor) *EndpointSource {
58		return &EndpointSource{
59			k8sCiliumEndpointsWatcher: k,
60			sp:                        sp,
61		}
62	}
63	
64	// Interface different data sources need to implement for usage with StreamProcessor.
65	type EndpointEventSource interface {
66		// Subscribe to Endpoint events.
67		SubscribeToEndpointEvents(ctx context.Context, wg *sync.WaitGroup)
68		ListAllEndpoints(ctx context.Context) ([]*types.CiliumEndpoint, error)
69	}
70	
71	func NewStreamProcessor(params *StreamProcessorParams) *StreamProcessor {
72		sp := &StreamProcessor{
73			stream:        params.Stream,
74			streamRecv:    params.StreamRecv,
75			endpointRecv:  params.EndpointEventRecv,
76			log:           params.Log,
77			expectedNonce: make(map[string]struct{}),
78		}
79		sp.endpointSource = NewEndpointSource(params.K8sCiliumEndpointsWatcher, sp)
80		return sp
81	}
