83	// convertCESToEndpointMap converts a CiliumEndpointSlice to a map of CiliumEndpoints
84	// keyed by namespace/name for easy lookup and comparison.
85	func convertCESToEndpointMap(ces *v2alpha1.CiliumEndpointSlice) map[string]*types.CiliumEndpoint {
86		result := make(map[string]*types.CiliumEndpoint, len(ces.Endpoints))
87		for _, coreCep := range ces.Endpoints {
88			cep := k8s.ConvertCoreCiliumEndpointToTypesCiliumEndpoint(&coreCep, ces.Namespace)
89			cepName := cep.Namespace + "/" + cep.Name
90			result[cepName] = cep
91		}
92		return result
93	}
94	
95	// computeEndpointDiff compares old and new endpoint maps and returns lists of
96	// endpoints that were added, updated, or removed.
97	func computeEndpointDiff(oldCEPs, newCEPs map[string]*types.CiliumEndpoint) (added, updated, removed []*types.CiliumEndpoint) {
98		// Find removed endpoints (in old but not in new)
99		for cepName, oldCEP := range oldCEPs {
100			if _, exists := newCEPs[cepName]; !exists {
101				removed = append(removed, oldCEP)
102			}
103		}
104	
105		// Find new or updated endpoints
106		for cepName, newCEP := range newCEPs {
107			if oldCEP, exists := oldCEPs[cepName]; !exists {
108				// New endpoint
109				added = append(added, newCEP)
110			} else if !oldCEP.DeepEqual(newCEP) {
111				// Updated endpoint
112				updated = append(updated, newCEP)
113			}
114		}
115	
116		return added, updated, removed
117	}
118	
119	// emitEndpointEvents sends endpoint events to the event channel.
120	func (es *EndpointSource) emitEndpointEvents(eventType EndpointEventType, endpoints []*types.CiliumEndpoint) {
121		for _, ep := range endpoints {
122			es.sp.endpointRecv <- &EndpointEvent{
123				Type:           eventType,
124				CiliumEndpoint: ep,
125			}
126		}
127	}
128	
129	// handleCESUpsert processes an upsert event for a CiliumEndpointSlice.
130	func (es *EndpointSource) handleCESUpsert(ces *v2alpha1.CiliumEndpointSlice, cesCache map[resource.Key]map[string]*types.CiliumEndpoint, key resource.Key) {
131		oldCEPs := cesCache[key]
132		if oldCEPs == nil {
133			oldCEPs = make(map[string]*types.CiliumEndpoint)
134		}
135	
136		newCEPs := convertCESToEndpointMap(ces)
137		added, updated, removed := computeEndpointDiff(oldCEPs, newCEPs)
138	
139		// Emit events for changes
140		es.emitEndpointEvents(REMOVED, removed)
141		es.emitEndpointEvents(CREATE, added)
142		es.emitEndpointEvents(CREATE, updated) // Updates are treated as CREATE
143	
144		// Update cache
145		cesCache[key] = newCEPs
146	}
147	
148	// handleCESDelete processes a delete event for a CiliumEndpointSlice.
149	func (es *EndpointSource) handleCESDelete(ces *v2alpha1.CiliumEndpointSlice, cesCache map[resource.Key]map[string]*types.CiliumEndpoint, key resource.Key) {
150		endpoints := convertCESToEndpointMap(ces)
151		endpointList := make([]*types.CiliumEndpoint, 0, len(endpoints))
152		for _, ep := range endpoints {
153			endpointList = append(endpointList, ep)
154		}
155		es.emitEndpointEvents(REMOVED, endpointList)
156		delete(cesCache, key)
157	}
158	
159	func (es *EndpointSource) SubscribeToEndpointEvents(ctx context.Context, wg *sync.WaitGroup) {
160		if option.Config.EnableCiliumEndpointSlice {
161			newSliceEvents := es.k8sCiliumEndpointsWatcher.GetCiliumEndpointSliceResource().Events(ctx, resource.WithErrorHandler(resource.AlwaysRetry))
162			// Keep track of CEPs in each CES to detect deletions on updates
163			cesCache := make(map[resource.Key]map[string]*types.CiliumEndpoint)
164	
165			for e := range newSliceEvents {
166				if e.Kind == resource.Sync {
167					wg.Done()
168					e.Done(nil)
169					continue
170				}
171				if e.Object == nil {
172					e.Done(nil)
173					continue
174				}
175	
176				switch e.Kind {
177				case resource.Upsert:
178					es.handleCESUpsert(e.Object, cesCache, e.Key)
179				case resource.Delete:
180					es.handleCESDelete(e.Object, cesCache, e.Key)
181				}
182	
183				e.Done(nil)
184			}
185			return
186		}
187	
188		// TODO(hemanthmalla): How should retries be configured here ?
189		newEvents := es.k8sCiliumEndpointsWatcher.GetCiliumEndpointResource().Events(ctx, resource.WithErrorHandler(resource.AlwaysRetry))
190		for e := range newEvents {
191			switch e.Kind {
192			case resource.Upsert:
193				es.sp.endpointRecv <- &EndpointEvent{
194					Type:           CREATE,
195					CiliumEndpoint: e.Object,
196				}
197			case resource.Delete:
198				es.sp.endpointRecv <- &EndpointEvent{
199					Type:           REMOVED,
200					CiliumEndpoint: e.Object,
201				}
202			case resource.Sync:
203				wg.Done()
204			}
205			e.Done(nil)
206		}
207	}
