14	type EnrolledNamespace struct {
15		Name   string
16		Status reconciler.Status // reconciliation status
17	}
18	
19	// TableHeader implements statedb.TableWritable.
20	func (ns *EnrolledNamespace) TableHeader() []string {
21		return []string{"Name", "Status"}
22	}
23	
24	// TableRow implements statedb.TableWritable.
25	func (ns *EnrolledNamespace) TableRow() []string {
26		return []string{ns.Name, ns.Status.String()}
27	}
28	
29	var _ statedb.TableWritable = &EnrolledNamespace{}
30	
31	// GetStatus returns the reconciliation status. Used to provide the
32	// reconciler access to it.
33	func (ns EnrolledNamespace) GetStatus() reconciler.Status {
34		return ns.Status
35	}
36	
37	// SetStatus sets the reconciliation status.
38	// Used by the reconciler to update the reconciliation status of the EnrolledNamespace.
39	func (ns *EnrolledNamespace) SetStatus(status reconciler.Status) *EnrolledNamespace {
40		ns.Status = status
41		return ns
42	}
43	
44	// Clone returns a shallow copy of the EnrolledNamespace.
45	func (ns *EnrolledNamespace) Clone() *EnrolledNamespace {
46		e := *ns
47		return &e
48	}
49	
50	// EnrolledNamespacesNameIndex allows looking up EnrolledNamespace by its name.
51	var EnrolledNamespacesNameIndex = statedb.Index[*EnrolledNamespace, string]{
52		Name: "name",
53		FromObject: func(ns *EnrolledNamespace) index.KeySet {
54			return index.NewKeySet(index.String(ns.Name))
55		},
56		FromKey: index.String,
57		Unique:  true,
58	}
59	
60	func NewEnrolledNamespacesTable(db *statedb.DB) (statedb.RWTable[*EnrolledNamespace], error) {
61		return statedb.NewTable(
62			db,
63			"mtls-enrolled-namespaces",
64			EnrolledNamespacesNameIndex,
65		)
66	}
67	
68	func K8sNamespaceToEnrolledNamespace(ns k8s.Namespace, deleted bool) (*EnrolledNamespace, statedb.DeriveResult) {
69		enrolled := true
70		if mtlsValue, exists := ns.Labels["io.cilium/mtls-enabled"]; !exists || mtlsValue != "true" {
71			enrolled = false
72		}
73		if deleted || !enrolled {
74			return &EnrolledNamespace{
75				Name:   ns.Name,
76				Status: reconciler.StatusPending(),
77			}, statedb.DeriveDelete
78		}
79		return &EnrolledNamespace{
80			Name:   ns.Name,
81			Status: reconciler.StatusPending(),
82		}, statedb.DeriveInsert
83	}
