// isNamespaceEnrolled returns true if the given namespace is enrolled in
// ztunnel mTLS.
func (es *EndpointSource) isNamespaceEnrolled(namespace string) bool {
	if es.sp == nil || es.sp.db == nil || es.sp.enrolledNamespaceTable == nil {
		return false
	}
	txn := es.sp.db.ReadTxn()
	_, _, found := es.sp.enrolledNamespaceTable.Get(txn, table.EnrolledNamespacesNameIndex.Query(namespace))
	return found
}

// filterEnrolledEvents drops events for endpoints whose namespace is not
// enrolled in ztunnel, as well as events with a nil endpoint.
func (es *EndpointSource) filterEnrolledEvents(events EndpointEventCollection) EndpointEventCollection {
	filtered := make(EndpointEventCollection, 0, len(events))
	for _, ev := range events {
		if ev == nil || ev.CiliumEndpoint == nil {
			continue
		}
		if !es.isNamespaceEnrolled(ev.Namespace) {
			continue
		}
		filtered = append(filtered, ev)
	}
	return filtered
